/* Meridiem · Olympe : polices et utilitaires. À importer dans le CSS principal : @import "./styles/olympe.css"; */
@import "@fontsource-variable/geist";
@import "@fontsource-variable/geist-mono";
@import "@fontsource/eb-garamond/latin-400.css";
@import "@fontsource/eb-garamond/latin-500.css";
@import "@fontsource/eb-garamond/latin-400-italic.css";

/* ============================================================
   Mode nuit Olympe : encre chaude, surfaces un cran plus claires,
   texte ivoire, terracotta éclairci pour l'action principale.
   Actif avec la classe .dark de shadcn (next-themes) ou avec
   <html data-theme="dark"> ; data-theme="auto" suit le système.
   Les deux blocs portent les mêmes valeurs : les modifier ensemble.
   Pour que les utilitaires dark: de shadcn suivent aussi data-theme, remplacer
   dans le CSS principal « @custom-variant dark (&:is(.dark *)); » par le bloc
   @custom-variant dark de DESIGN.md (§ Mode nuit).
   ============================================================ */
.dark,
:root[data-theme="dark"] {
  color-scheme: dark;

  /* Rôles shadcn */
  --background: #181513;
  --foreground: #EEE7DB;
  --card: #211D19;
  --card-foreground: #EEE7DB;
  --popover: #262119;
  --popover-foreground: #EEE7DB;
  --primary: #D9773F;
  --primary-foreground: #1A1410;
  --secondary: #2B2621;
  --secondary-foreground: #EEE7DB;
  --muted: #2B2621;
  --muted-foreground: #A9A095;
  --accent: #2E2823;
  --accent-foreground: #EEE7DB;
  --destructive: #EE7D70;
  --border: #36302A;
  --input: #453D35;
  --ring: #C98A5E;

  /* Graphiques : même ordre, éclaircis (validés au script dataviz sur la carte) */
  --chart-1: #D9773F;
  --chart-2: #7489E2;
  --chart-3: #C3841A;
  --chart-4: #2AA88C;
  --chart-5: #BE72CC;

  --sidebar: #12100E;
  --sidebar-foreground: #D6CEC2;
  --sidebar-primary: #EEE7DB;
  --sidebar-primary-foreground: #1A1410;
  --sidebar-accent: #26211C;
  --sidebar-accent-foreground: #EEE7DB;
  --sidebar-border: #2A2520;
  --sidebar-ring: #C98A5E;

  /* Statuts éclaircis (≥ 4,5:1 sur leur fond de badge), toujours doublés d'un mot */
  --ok: #6CC08A;
  --warn: #E3A55A;
  --wait: #AFA2EE;
  --crit: #F2867A;
  --info: #80B2E8;
}

@media (prefers-color-scheme: dark) {
  :root[data-theme="auto"] {
    color-scheme: dark;

    /* Rôles shadcn */
    --background: #181513;
    --foreground: #EEE7DB;
    --card: #211D19;
    --card-foreground: #EEE7DB;
    --popover: #262119;
    --popover-foreground: #EEE7DB;
    --primary: #D9773F;
    --primary-foreground: #1A1410;
    --secondary: #2B2621;
    --secondary-foreground: #EEE7DB;
    --muted: #2B2621;
    --muted-foreground: #A9A095;
    --accent: #2E2823;
    --accent-foreground: #EEE7DB;
    --destructive: #EE7D70;
    --border: #36302A;
    --input: #453D35;
    --ring: #C98A5E;

    /* Graphiques : même ordre, éclaircis (validés au script dataviz sur la carte) */
    --chart-1: #D9773F;
    --chart-2: #7489E2;
    --chart-3: #C3841A;
    --chart-4: #2AA88C;
    --chart-5: #BE72CC;

    --sidebar: #12100E;
    --sidebar-foreground: #D6CEC2;
    --sidebar-primary: #EEE7DB;
    --sidebar-primary-foreground: #1A1410;
    --sidebar-accent: #26211C;
    --sidebar-accent-foreground: #EEE7DB;
    --sidebar-border: #2A2520;
    --sidebar-ring: #C98A5E;

    /* Statuts éclaircis (≥ 4,5:1 sur leur fond de badge), toujours doublés d'un mot */
    --ok: #6CC08A;
    --warn: #E3A55A;
    --wait: #AFA2EE;
    --crit: #F2867A;
    --info: #80B2E8;
  }
}

@layer components {
  /* Étiquette en capitales (rubriques, colonnes) */
  .eyebrow {
    @apply font-mono text-[11px] font-medium tracking-[0.08em] uppercase text-muted-foreground;
  }
  /* Grille de filets à repères en croix (Olympus) */
  .hairline-grid {
    @apply grid border-t border-l border-border;
  }
  .hairline-grid > * {
    @apply relative border-r border-b border-border;
  }
  .hairline-grid > *::after {
    content: "";
    position: absolute;
    right: -5px;
    bottom: -5px;
    width: 9px;
    height: 9px;
    background:
      linear-gradient(var(--ring), var(--ring)) center / 9px 1px no-repeat,
      linear-gradient(var(--ring), var(--ring)) center / 1px 9px no-repeat;
    opacity: 0.7;
    z-index: 1;
  }
  .num {
    font-variant-numeric: tabular-nums;
  }
}

/* Graphiques : pas de cadre de focus au clic (Recharts rend la zone focusable), anneau discret au clavier seulement */
.recharts-wrapper,
.recharts-wrapper * {
  outline: none !important;
}
.recharts-wrapper:focus-visible {
  outline: 2px solid var(--ring) !important;
  outline-offset: 4px;
  border-radius: 8px;
}

/* Entrées douces : chaque enfant d'une page ou d'une grille monte en cascade */
@keyframes rise {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
.stagger > * {
  animation: rise 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}
.stagger > *:nth-child(2) { animation-delay: 0.05s; }
.stagger > *:nth-child(3) { animation-delay: 0.1s; }
.stagger > *:nth-child(4) { animation-delay: 0.15s; }
.stagger > *:nth-child(5) { animation-delay: 0.2s; }
.stagger > *:nth-child(n + 6) { animation-delay: 0.25s; }
[data-slot="tabs-content"][data-state="active"] {
  animation: rise 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
